char * rand_string_nonce(char * str, size_t str_size) { /* <=== rand_string_nonce */ 
  const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
  size_t n;

  if (str_size && str != NULL) {
    for (n = 0; n < str_size; n++) {
      str[n] = charset[random_at_most((sizeof(charset)) - 2, 1)];
    }
    str[str_size] = '\0';
    return str;
  } else {
    return NULL;
  }
}

int generate_digest_crypt(const char * data, const char * method, char * out_digest) { /* <=== generate_digest_crypt */ 
  char salt[GLEWLWYD_DEFAULT_SALT_LENGTH+4] = {0},  * out_crypt;
  int res;

  if (method != NULL) {
    o_strcpy(salt, method);
  }
  rand_string_nonce(salt+o_strlen(method), GLEWLWYD_DEFAULT_SALT_LENGTH);
  if ((out_crypt = crypt(data, salt)) != NULL) {
    o_strcpy(out_digest, out_crypt);
    res = 1;
  } else {
    res = 0;
  }
  return res;
}

